65	/// Shared command-line option grammar for `sign` and `verify`.
66	///
67	/// Both subcommands accept the same two spellings for every option:
68	///   --name value     (the following argument is the value, even when it
69	///                    itself starts with "--")
70	///   --name=value     (everything after the first '=' is the value; further
71	///                    '=' characters stay part of the value)
72	/// and the two forms may be mixed freely.
73	///
74	/// What differs between the subcommands is only *which* option names are
75	/// allowed and whether a name may repeat, so each caller supplies its own
76	/// option table. Values that fail are never quoted back in error messages:
77	/// the messages name known options only, never the rejected text (which may
78	/// be a mistyped secret).
79	mod options {
80	    /// How many times an option name may appear on one command line.
81	    #[derive(Clone, Copy, PartialEq, Eq)]
82	    pub(super) enum Multiplicity {
83	        /// At most once; a second occurrence is a usage error.
84	        Single,
85	        /// Any number of times; values are kept in order of appearance.
86	        Repeated,
87	    }
88	
89	    /// One option accepted by a subcommand.
90	    pub(super) struct Spec {
91	        pub(super) name: &'static str,
92	        pub(super) multiplicity: Multiplicity,
93	    }
94	
95	    /// A matched option occurrence: the option's index in the table and its
96	    /// value for this occurrence.
97	    pub(super) struct Occurrence {
98	        pub(super) spec_index: usize,
99	        pub(super) value: String,
100	    }
101	
102	    /// Parse `args` against `specs`, preserving order of appearance.
103	    ///
104	    /// Error precedence (first problem wins, left to right):
105	    /// missing value for an option, repeated single-use option, unknown
106	    /// option or bare argument. Callers run their own semantic validation
107	    /// (hex, ranges, ...) afterwards, so grammar problems are always
108	    /// reported before invalid values.
109	    pub(super) fn parse(args: &[String], specs: &[Spec]) -> Result<Vec<Occurrence>, String> {
110	        let mut out = Vec::new();
111	        let mut seen_once = vec![false; specs.len()];
112	
113	        let mut i = 0;
114	        while i < args.len() {
115	            let arg = &args[i];
116	            // Support both "--opt value" and "--opt=value" forms. With '='
117	            // the value is everything after the FIRST '='; '=' characters
118	            // inside the value are left untouched.
119	            let (name, inline_value) = match arg.split_once('=') {
120	                Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
121	                _ => (arg.as_str(), None),
122	            };
123	            let spec_index = match specs.iter().position(|s| s.name == name) {
124	                Some(idx) => idx,
125	                // Never echo the unrecognized argument itself: it may be a
126	                // misplaced secret (e.g. a key value whose option name was
127	                // mistyped or whose value was consumed by another option).
128	                None => return Err(unknown_option_error(specs)),
129	            };
130	            let value = match inline_value {
131	                Some(v) => v,
132	                None => {
133	                    // The immediately following argument is the value, with
134	                    // no "--"-prefix special-casing: a field or key id may
135	                    // legitimately start with two dashes.
136	                    i += 1;
137	                    match args.get(i) {
138	                        Some(v) => v.clone(),
139	                        None => return Err(format!("option {name} requires a value")),
140	                    }
141	                }
142	            };
143	            if specs[spec_index].multiplicity == Multiplicity::Single && seen_once[spec_index] {
144	                return Err(format!("option {name} must be given exactly once"));
145	            }
146	            seen_once[spec_index] = true;
147	            out.push(Occurrence { spec_index, value });
148	            i += 1;
149	        }
150	        Ok(out)
151	    }
152	
153	    /// Build the fixed "unrecognized" message for a subcommand, listing only
154	    /// that subcommand's known option names. The rejected argument is never
155	    /// included.
156	    fn unknown_option_error(specs: &[Spec]) -> String {
157	        let names = specs
158	            .iter()
159	            .map(|s| s.name)
160	            .collect::<Vec<_>>()
161	            .join(", ");
162	        if specs.len() == 1 {
163	            format!("unrecognized option or argument (the only known option is {names})")
164	        } else {
165	            format!("unrecognized option or argument (known options: {names})")
166	        }
167	    }
168	}
