170	fn sign(args: &[String]) -> ExitCode {
171	    match parse_sign_args(args).and_then(validate_sign_args) {
172	        Ok(opts) => {
173	            let key_bytes = decode_hex(&opts.key).expect("key was validated as hex");
174	            let key_version: u32 = opts.key_version.parse().expect("version was validated");
175	            let message = encode_message(&opts.key_id, key_version, &opts.fields);
176	            let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
177	                .expect("HMAC accepts keys of any length");
178	            mac.update(&message);
179	            let tag = mac.finalize().into_bytes();
180	
181	            let fields_json = opts
182	                .fields
183	                .iter()
184	                .map(|f| format!("\"{}\"", json_escape(f)))
185	                .collect::<Vec<_>>()
186	                .join(",");
187	            println!(
188	                "{{\"format\":{FORMAT_VERSION},\"algorithm\":\"{ALGORITHM}\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
189	                json_escape(&opts.key_id),
190	                key_version,
191	                fields_json,
192	                hex_encode(&tag),
193	            );
194	            ExitCode::SUCCESS
195	        }
196	        Err(msg) => {
197	            eprintln!("authnote sign: {msg}");
198	            ExitCode::from(2)
199	        }
200	    }
201	}
202	
203	struct SignOptions {
204	    key: String,
205	    key_id: String,
206	    key_version: String,
207	    fields: Vec<String>,
208	}
209	
210	/// sign's option table: the three credential/metadata options are single
211	/// use; only --field may repeat. Names double as their stable indices.
212	const SIGN_OPTIONS: &[options::Spec] = &[
213	    options::Spec {
214	        name: "--key",
215	        multiplicity: options::Multiplicity::Single,
216	    },
217	    options::Spec {
218	        name: "--key-id",
219	        multiplicity: options::Multiplicity::Single,
220	    },
221	    options::Spec {
222	        name: "--key-version",
223	        multiplicity: options::Multiplicity::Single,
224	    },
225	    options::Spec {
226	        name: "--field",
227	        multiplicity: options::Multiplicity::Repeated,
228	    },
229	];
230	const SIGN_KEY_INDEX: usize = 0;
231	const SIGN_KEY_ID_INDEX: usize = 1;
232	const SIGN_KEY_VERSION_INDEX: usize = 2;
233	
234	fn parse_sign_args(args: &[String]) -> Result<SignOptions, String> {
235	    let mut key: Option<String> = None;
236	    let mut key_id: Option<String> = None;
237	    let mut key_version: Option<String> = None;
238	    let mut fields: Vec<String> = Vec::new();
239	
240	    for occurrence in options::parse(args, SIGN_OPTIONS)? {
241	        match occurrence.spec_index {
242	            SIGN_KEY_INDEX => key = Some(occurrence.value),
243	            SIGN_KEY_ID_INDEX => key_id = Some(occurrence.value),
244	            SIGN_KEY_VERSION_INDEX => key_version = Some(occurrence.value),
245	            // Field values are appended in order of appearance; repeats,
246	            // empty strings and text starting with "--" are kept verbatim.
247	            _ => fields.push(occurrence.value),
248	        }
249	    }
250	
251	    let key = key.ok_or("missing required option --key")?;
252	    let key_id = key_id.ok_or("missing required option --key-id")?;
253	    let key_version = key_version.ok_or("missing required option --key-version")?;
254	    Ok(SignOptions {
255	        key,
256	        key_id,
257	        key_version,
258	        fields,
259	    })
260	}
261	
262	fn validate_sign_args(opts: SignOptions) -> Result<SignOptions, String> {
263	    // Never echo the key back in error messages.
264	    validate_key_hex(&opts.key)?;
265	    if opts.key_id.is_empty() {
266	        return Err("--key-id must not be empty".to_string());
267	    }
268	    let valid_version = !opts.key_version.is_empty()
269	        && opts.key_version.bytes().all(|b| b.is_ascii_digit())
270	        && opts
271	            .key_version
272	            .parse::<u64>()
273	            .is_ok_and(|v| (1..=u32::MAX as u64).contains(&v));
274	    if !valid_version {
275	        return Err("--key-version must be a decimal integer between 1 and 4294967295".to_string());
276	    }
277	    Ok(opts)
278	}
