1004	    #[test]
1005	    fn verify_accepts_valid_records() {
1006	        let key = "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b";
1007	        // Zero fields vs one empty field are both valid and distinct.
1008	        assert!(matches!(
1009	            verify_input(record_for(key, "id", 1, &[]).as_bytes(), key),
1010	            VerifyOutcome::Valid
1011	        ));
1012	        assert!(matches!(
1013	            verify_input(record_for(key, "id", 1, &[""]).as_bytes(), key),
1014	            VerifyOutcome::Valid
1015	        ));
1016	        // Unicode, duplicate and reordered fields.
1017	        let rec = record_for(key, "demo", 3, &["hello", "世界", "世界"]);
1018	        assert!(matches!(verify_input(rec.as_bytes(), key), VerifyOutcome::Valid));
1019	        // Surrounding JSON whitespace and internal reformatting are fine.
1020	        let pretty = format!(
1021	            " \n\t{}  \r\n",
1022	            rec.replace(',', ",\n  ").replace('{', "{\n  ")
1023	        );
1024	        assert!(matches!(
1025	            verify_input(pretty.as_bytes(), key),
1026	            VerifyOutcome::Valid
1027	        ));
1028	        // Member order must not matter.
1029	        let reordered = "{\"tag\":\"X\",\"fields\":[],\"key_version\":1,\"key_id\":\"id\",\
1030	                         \"algorithm\":\"HMAC-SHA256\",\"format\":1}";
1031	        // Recompute with the real tag to keep this a positive case.
1032	        let mut reordered = reordered.to_string();
1033	        let tag = sign_tag(key, "id", 1, &[]);
1034	        reordered = reordered.replace('X', &tag);
1035	        assert!(matches!(
1036	            verify_input(reordered.as_bytes(), key),
1037	            VerifyOutcome::Valid
1038	        ));
1039	        // Uppercase tag spelling still represents the same 32 bytes.
1040	        let real_tag = sign_tag(key, "id", 1, &["x"]);
1041	        let upper = record_for(key, "id", 1, &["x"]).replace(&real_tag, &real_tag.to_uppercase());
1042	        assert!(matches!(
1043	            verify_input(upper.as_bytes(), key),
1044	            VerifyOutcome::Valid
1045	        ));
1046	    }
