386	// ---------------------------------------------------------------------------
387	// Minimal JSON parser (objects, arrays, strings, integers, true/false/null).
388	// ---------------------------------------------------------------------------
389	
390	#[derive(Debug, Clone)]
391	enum Json {
392	    Null,
393	    // Retained for parser completeness; records carry no boolean values.
394	    #[allow(dead_code)]
395	    Bool(bool),
396	    Num(i64),
397	    Str(String),
398	    Arr(Vec<Json>),
399	    Obj(Vec<(String, Json)>),
400	}
401	
402	impl Json {
403	    fn parse(s: &str) -> Json {
404	        let mut p = Parser {
405	            chars: s.chars().collect(),
406	            pos: 0,
407	        };
408	        p.ws();
409	        let v = p.value();
410	        p.ws();
411	        assert_eq!(p.pos, p.chars.len(), "trailing data after JSON record: {s}");
412	        v
413	    }
414	
415	    fn as_str(&self) -> &str {
416	        match self {
417	            Json::Str(s) => s,
418	            other => panic!("expected JSON string, got {other:?}"),
419	        }
420	    }
421	
422	    fn as_i64(&self) -> i64 {
423	        match self {
424	            Json::Num(n) => *n,
425	            other => panic!("expected JSON number, got {other:?}"),
426	        }
427	    }
428	
429	    fn as_array(&self) -> &[Json] {
430	        match self {
431	            Json::Arr(a) => a,
432	            other => panic!("expected JSON array, got {other:?}"),
433	        }
434	    }
435	
436	    fn as_object(&self) -> &[(String, Json)] {
437	        match self {
438	            Json::Obj(o) => o,
439	            other => panic!("expected JSON object, got {other:?}"),
440	        }
441	    }
442	
443	    fn get(&self, key: &str) -> &Json {
444	        let obj = self.as_object();
445	        let idx = obj
446	            .iter()
447	            .position(|(k, _)| k == key)
448	            .unwrap_or_else(|| panic!("missing key {key:?} in {self:?}"));
449	        &obj[idx].1
450	    }
451	
452	    /// Every string value anywhere in the document.
453	    fn strings(&self, out: &mut Vec<String>) {
454	        match self {
455	            Json::Str(s) => out.push(s.clone()),
456	            Json::Arr(a) => a.iter().for_each(|v| v.strings(out)),
457	            Json::Obj(o) => o.iter().for_each(|(_, v)| v.strings(out)),
458	            Json::Null | Json::Bool(_) | Json::Num(_) => {}
459	        }
460	    }
461	}
462	
463	struct Parser {
464	    chars: Vec<char>,
465	    pos: usize,
466	}
467	
468	impl Parser {
469	    fn ws(&mut self) {
470	        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
471	            self.pos += 1;
472	        }
473	    }
474	
475	    fn bump(&mut self) -> char {
476	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
477	        let c = self.chars[self.pos];
478	        self.pos += 1;
479	        c
480	    }
481	
482	    fn expect(&mut self, want: char) {
483	        assert!(self.pos < self.chars.len(), "expected {want:?}, found end of JSON");
484	        let got = self.chars[self.pos];
485	        assert_eq!(got, want, "expected {want:?} at position {}", self.pos);
486	        self.pos += 1;
487	    }
488	
489	    fn value(&mut self) -> Json {
490	        self.ws();
491	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
492	        match self.chars[self.pos] {
493	            '{' => self.object(),
494	            '[' => self.array(),
495	            '"' => Json::Str(self.string()),
496	            't' | 'f' => self.boolean(),
497	            'n' => self.null(),
498	            c if c == '-' || c.is_ascii_digit() => self.number(),
499	            c => panic!("unexpected character {c:?} in JSON"),
500	        }
501	    }
502	
503	    fn object(&mut self) -> Json {
504	        self.expect('{');
505	        let mut entries = Vec::new();
506	        self.ws();
507	        if self.chars[self.pos] == '}' {
508	            self.pos += 1;
509	            return Json::Obj(entries);
510	        }
511	        loop {
512	            self.ws();
513	            let key = self.string();
514	            self.ws();
515	            self.expect(':');
516	            let val = self.value();
517	            entries.push((key, val));
518	            self.ws();
519	            match self.bump() {
520	                ',' => continue,
521	                '}' => break,
522	                c => panic!("bad object separator {c:?}"),
523	            }
524	        }
525	        Json::Obj(entries)
526	    }
527	
528	    fn array(&mut self) -> Json {
529	        self.expect('[');
530	        let mut items = Vec::new();
531	        self.ws();
532	        if self.chars[self.pos] == ']' {
533	            self.pos += 1;
534	            return Json::Arr(items);
535	        }
536	        loop {
537	            items.push(self.value());
538	            self.ws();
539	            match self.bump() {
540	                ',' => continue,
541	                ']' => break,
542	                c => panic!("bad array separator {c:?}"),
543	            }
544	        }
545	        Json::Arr(items)
546	    }
547	
548	    fn string(&mut self) -> String {
549	        self.expect('"');
550	        let mut out = String::new();
551	        loop {
552	            match self.bump() {
553	                '"' => break,
554	                '\\' => match self.bump() {
555	                    '"' => out.push('"'),
556	                    '\\' => out.push('\\'),
557	                    '/' => out.push('/'),
558	                    'b' => out.push('\u{0008}'),
559	                    'f' => out.push('\u{000c}'),
560	                    'n' => out.push('\n'),
561	                    'r' => out.push('\r'),
562	                    't' => out.push('\t'),
563	                    'u' => {
564	                        let hi = self.hex4();
565	                        let c = if (0xD800..=0xDBFF).contains(&hi) {
566	                            assert_eq!(self.bump(), '\\');
567	                            assert_eq!(self.bump(), 'u');
568	                            let lo = self.hex4();
569	                            assert!(
570	                                (0xDC00..=0xDFFF).contains(&lo),
571	                                "bad low surrogate {lo:x}"
572	                            );
573	                            char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
574	                                .expect("bad surrogate pair")
575	                        } else {
576	                            char::from_u32(hi).expect("bad unicode escape")
577	                        };
578	                        out.push(c);
579	                    }
580	                    c => panic!("bad escape \\{c}"),
581	                },
582	                // Raw control bytes must not appear unescaped in JSON text.
583	                c if (c as u32) < 0x20 => panic!("unescaped control character {c:?} in JSON"),
584	                c => out.push(c),
585	            }
586	        }
587	        out
588	    }
589	
590	    fn hex4(&mut self) -> u32 {
591	        let mut v = 0u32;
592	        for _ in 0..4 {
593	            let c = self.bump();
594	            v = v * 16 + c.to_digit(16).unwrap_or_else(|| panic!("bad hex digit {c:?}"));
595	        }
596	        v
597	    }
598	
599	    fn number(&mut self) -> Json {
600	        let start = self.pos;
601	        if self.chars[self.pos] == '-' {
602	            self.pos += 1;
603	        }
604	        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
605	            self.pos += 1;
606	        }
607	        let text: String = self.chars[start..self.pos].iter().collect();
608	        Json::Num(text.parse().unwrap_or_else(|_| panic!("bad number {text}")))
609	    }
610	
611	    fn boolean(&mut self) -> Json {
612	        if self.chars[self.pos] == 't' {
613	            for want in "true".chars() {
614	                self.expect(want);
615	            }
616	            Json::Bool(true)
617	        } else {
618	            for want in "false".chars() {
619	                self.expect(want);
620	            }
621	            Json::Bool(false)
622	        }
623	    }
624	
625	    fn null(&mut self) -> Json {
626	        for want in "null".chars() {
627	            self.expect(want);
628	        }
629	        Json::Null
630	    }
