648	/// Parse the sole JSON record on stdout, enforcing the observable contract:
649	/// exactly one line, exactly the six documented keys in documented order,
650	/// format 1, fixed algorithm name, valid version range, 64 lowercase hex tag.
651	fn parse_single_record(stdout: &[u8]) -> Record {
652	    let text = std::str::from_utf8(stdout).expect("stdout must be valid UTF-8");
653	    assert!(text.starts_with('{'), "stdout must start with the JSON object");
654	    let body = text
655	        .strip_suffix('\n')
656	        .expect("stdout must end with exactly one newline");
657	    assert!(!body.is_empty(), "stdout must contain one JSON record");
658	    assert!(!body.contains('\n'), "stdout must contain exactly one line");
659	    assert!(!body.ends_with('\r'), "line must not carry a carriage return");
660	
661	    let raw = Json::parse(body);
662	    let keys: Vec<&str> = raw.as_object().iter().map(|(k, _)| k.as_str()).collect();
663	    assert_eq!(
664	        keys,
665	        vec![
666	            "format",
667	            "algorithm",
668	            "key_id",
669	            "key_version",
670	            "fields",
671	            "tag"
672	        ],
673	        "record field structure must stay compatible"
674	    );
675	
676	    let fields = raw
677	        .get("fields")
678	        .as_array()
679	        .iter()
680	        .map(|v| v.as_str().to_string())
681	        .collect();
682	
683	    let rec = Record {
684	        format: raw.get("format").as_i64(),
685	        algorithm: raw.get("algorithm").as_str().to_string(),
686	        key_id: raw.get("key_id").as_str().to_string(),
687	        key_version: raw.get("key_version").as_i64(),
688	        fields,
689	        tag: raw.get("tag").as_str().to_string(),
690	        raw,
691	    };
692	
693	    assert_eq!(rec.format, 1, "format must always be 1");
694	    assert_eq!(rec.algorithm, "HMAC-SHA256");
695	    assert!(
696	        (1..=u32::MAX as i64).contains(&rec.key_version),
697	        "key_version out of range: {}",
698	        rec.key_version
699	    );
700	    assert_eq!(rec.tag.len(), 64, "tag must be 64 hex characters");
701	    assert!(
702	        rec.tag
703	            .bytes()
704	            .all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')),
705	        "tag must be lowercase hex, got {}",
706	        rec.tag
707	    );
708	    rec
709	}
710	
711	/// Successful invocation: exit code 0, empty stderr, one valid record whose
712	/// fields/key-id/version match the inputs and whose tag equals the golden
713	/// value computed independently of this implementation.
714	fn expect_signed_record(
715	    label: &str,
716	    key: &str,
717	    key_id: &str,
718	    version: &str,
719	    fields: &[&str],
720	    golden_tag: &str,
721	) -> Record {
722	    let out = run_sign(key, key_id, version, fields);
723	    assert_eq!(
724	        out.status.code(),
725	        Some(0),
726	        "{label}: expected exit 0, got {:?}, stderr={:?}",
727	        out.status.code(),
728	        String::from_utf8_lossy(&out.stderr)
729	    );
730	    assert!(
731	        out.stderr.is_empty(),
732	        "{label}: stderr must be empty, got {:?}",
733	        String::from_utf8_lossy(&out.stderr)
734	    );
735	
736	    let rec = parse_single_record(&out.stdout);
737	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
738	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
739	    assert_eq!(
740	        rec.key_version,
741	        version.parse::<i64>().unwrap(),
742	        "{label}: key_version mismatch"
743	    );
744	    assert_eq!(
745	        rec.fields,
746	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
747	        "{label}: parsed fields must be character-identical to the inputs"
748	    );
749	
750	    // The raw key is used only for the MAC: it must never appear as a value
751	    // anywhere in the record (compared as a whole string, not a substring, so
752	    // short keys cannot clash with random fragments of the 64-char tag).
753	    let needle = key.to_lowercase();
754	    let mut strings = Vec::new();
755	    rec.raw.strings(&mut strings);
756	    assert!(
757	        strings.iter().all(|s| s.to_lowercase() != needle),
758	        "{label}: raw key material must not be part of the record"
759	    );
760	    rec
761	}
